import {displayCity} from './lib/discovery/destination-identity.js';
import {displayLabel} from './lib/display-localization.js';
import {LocalDestinationVisualProvider} from './lib/discovery/destination-visual-provider.js';
import {destinationIdentity} from './lib/discovery/destination-identity.js';
import {navigationForCountry} from './lib/providers/navigation-provider.js';

const visualProvider=new LocalDestinationVisualProvider();
const e=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const label=(language,zh,en)=>language==='zh'?zh:en;
export const MAX_TRIP_COLLAGE_IMAGES=1;
const imageAttribution=(image,language)=>image?.kind==='photograph'&&image?.sourceUrl?`<small class="photo-attribution">${label(language,'照片','Photo')}: <a href="${e(image.sourceUrl)}" target="_blank" rel="noreferrer">${e(image.author||image.source)}</a>${image.license?` · ${image.licenseUrl?`<a href="${e(image.licenseUrl)}" target="_blank" rel="noreferrer">${e(image.license)}</a>`:e(image.license)}`:''}</small>`:'';

const shortDate=(value,language)=>value?new Date(`${value.slice(0,10)}T00:00:00Z`).toLocaleDateString(language==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'';
const shortTime=value=>/^\d{4}-\d\d-\d\dT\d\d:\d\d/.test(value||'')?value.slice(11,16):null;
const duration=(from,to)=>{if(!from||!to)return null;const minutes=Math.round((Date.parse(to)-Date.parse(from))/60000);return Number.isFinite(minutes)&&minutes>0?minutes:null;};
const durationText=(minutes,language)=>minutes==null?'':language==='zh'?`${Math.floor(minutes/60)}小时${minutes%60?`${minutes%60}分`:''}`:`${Math.floor(minutes/60)}h ${minutes%60?`${minutes%60}m`:''}`;
const paceLabel=(pace,language)=>({relaxed:label(language,'轻松游','Relaxed'),balanced:label(language,'经典体验','Balanced'),intensive:label(language,'高效打卡','Intensive'),deep_dive:label(language,'深度体验','Deep dive')})[pace]||label(language,'经典体验','Balanced');
const spendingLabel=(value,language)=>value==='comfort'?label(language,'舒适优先','Comfort'):label(language,'性价比','Value');

export function tripHeroImages(destination,resolvedVisual=null){const visual=resolvedVisual||visualProvider.getVisual(destination),primary=visual.heroImages[0];return [primary].filter(Boolean).slice(0,MAX_TRIP_COLLAGE_IMAGES);}
export function renderTripHero(experience,language='zh',resolvedVisual=null){
 const identity=destinationIdentity(experience.trip.destination),city=displayCity(experience.trip.destination,language),origin=displayCity(experience.trip.origin,language),images=tripHeroImages(experience.trip.destination,resolvedVisual),image=images[0],window=experience.plan?.windows?.[0];
 const dates=window?`${shortDate(window.departure,language)}–${shortDate(window.returnDate,language)}`:label(language,'日期灵活','Flexible dates');
 return `<div class="trip-hero" data-trip-hero="${e(identity.key)}"><div class="trip-hero-copy"><span>${label(language,'这趟旅行','THIS TRIP')}</span><strong class="trip-hero-route-title">${e(origin)} → ${e(city)}</strong><p class="trip-hero-facts">${e(dates)} · ${e(experience.trip.nights)}${label(language,'晚',' nights')}</p><p>${e(paceLabel(experience.itinerary.pace,language))} · ${e(spendingLabel(experience.trip.spendingOrientation,language))}</p><div class="trip-summary-actions"><button type="button" data-trip-action="date">${label(language,'更换日期','Change dates')}</button><button type="button" data-trip-action="duration">${label(language,'调整天数','Change length')}</button><button type="button" data-trip-action="style">${label(language,'调整旅行方式','Change trip style')}</button></div></div>${image?`<figure class="trip-hero-media" data-trip-hero-visual="${e(identity.key)}"><img class="trip-hero-image" src="${e(image.src)}" alt="${e(image.description)}" loading="eager" decoding="async">${imageAttribution(image,language)}</figure>`:''}</div>`;
}

export function renderFlightDetails(quote,source,language='zh',route=null){
 if(!quote)return `<p class="trip-availability">${label(language,'航班时间与价格尚未核验','Flight times and price are not verified')}</p>`;
 const segments=Array.isArray(quote.segments)?quote.segments:[],outbound=segments.filter(segment=>segment.slice==='outbound'),inbound=segments.filter(segment=>segment.slice==='return');
 const leg=(items,departure,heading)=>{const first=items[0],last=items.at(-1),start=first?.departingAt||departure,end=last?.arrivingAt||null,times=start&&end?`${shortTime(start)}–${shortTime(end)}`:null,legRoute=first?.origin&&last?.destination?`${first.origin} → ${last.destination}`:null;return `<div class="flight-leg"><b>${heading}</b><span>${legRoute?`${e(legRoute)} · `:''}${start?`${e(shortDate(start,language))} · `:''}${times?e(times):label(language,'到达时间待提供','Arrival time unavailable')}</span>${times?`<small>${e(durationText(duration(start,end),language))}</small>`:''}</div>`;};
 const sourceLabel=source==='live'?label(language,'已核验 · Duffel','Verified · Duffel'):label(language,'演示航班参考','Demo flight reference');
 const stopText=quote.stops===0?label(language,'直飞','Nonstop'):Number.isInteger(quote.stops)?label(language,`${quote.stops} 次中转`,`${quote.stops} stop${quote.stops===1?'':'s'}`):'';
 const amount=quote.currency==='CNY'&&Number.isFinite(quote.price)?`¥${Math.round(quote.price).toLocaleString('en-US')}`:label(language,'价格待核验','Price unverified');
 return `<div class="flight-summary"><span>${e(sourceLabel)}</span>${route?`<span>${e(route.from)} → ${e(route.to)}</span>`:''}<strong>${e(amount)}</strong><small>${e(stopText)}${quote.airline?` · ${e(quote.airline)}`:''}</small></div><details class="flight-details"><summary>${label(language,'查看航班','View flight')}</summary>${outbound.length?leg(outbound,quote.departureDateTime,label(language,'去程','Outbound')):quote.departureDateTime?`<p>${label(language,'去程出发','Outbound departure')} ${e(shortDate(quote.departureDateTime,language))} ${e(shortTime(quote.departureDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:`<p>${label(language,'航班时间暂未提供','Flight times unavailable')}</p>`}${inbound.length?leg(inbound,quote.returnDateTime,label(language,'返程','Return')):quote.returnDateTime?`<p>${label(language,'返程出发','Return departure')} ${e(shortDate(quote.returnDateTime,language))} ${e(shortTime(quote.returnDateTime)||'')} · ${label(language,'到达时间待提供','Arrival time unavailable')}</p>`:''}</details>`;
}

function renderStyleControls(experience,language){
 const pace=experience.itinerary.pace,spending=experience.trip.spendingOrientation||'value';
 const paceOptions=[['relaxed','轻松游','Relaxed'],['balanced','经典体验','Balanced'],['intensive','高效打卡','Intensive']];
 const spendOptions=[['value','性价比','Value'],['comfort','舒适优先','Comfort']];
 return `<div class="trip-style-controls"><div><span>${label(language,'旅行节奏','Travel pace')}</span><div class="trip-pace" role="group" aria-label="${label(language,'旅行节奏','Travel pace')}">${paceOptions.map(([key,zh,en])=>`<button type="button" data-trip-pace="${key}" aria-pressed="${pace===key}">${label(language,zh,en)}</button>`).join('')}</div></div><div><span>${label(language,'花费取向','Spending orientation')}</span><div class="trip-spending" role="group" aria-label="${label(language,'花费取向','Spending orientation')}">${spendOptions.map(([key,zh,en])=>`<button type="button" data-trip-spending="${key}" aria-pressed="${spending===key}">${label(language,zh,en)}</button>`).join('')}</div></div></div>`;
}

export function renderTripTimingControls(experience,language='zh',openPanel=null){
 const plan=experience.plan,window=plan?.windows?.[0],nights=experience.trip.nights;
 const dates=window?`${shortDate(window.departure,language)} – ${shortDate(window.returnDate,language)}`:label(language,'日期灵活','Flexible dates');
 const budget=experience.trip.flightBudget==null&&experience.trip.hotelBudget==null?label(language,'预算未设','No budget set'):label(language,'已设置预算','Budget set');
 return `<section class="trip-module trip-timing" data-trip-module="timing"><div class="trip-module-heading"><span>01</span><h3>${label(language,'什么时候去','Timing')}</h3></div><p class="trip-current-label">${label(language,'当前推荐','CURRENT PLAN')}</p><p class="trip-current-date"><strong>${e(dates)}</strong> · ${e(nights)} ${label(language,'晚','nights')}</p><p class="trip-availability">${plan?.dateSource==='user_provided'?label(language,'你提供的日期','Your dates'):label(language,'系统探索日期 · 尚未锁定','Provisional exploration dates · not locked')} · ${budget}</p><div class="trip-actions"><button type="button" data-trip-action="date">${label(language,'更换日期','Change dates')}</button><button type="button" data-trip-action="duration">${label(language,'调整天数','Change length')}</button></div><div class="trip-inline-editor" data-trip-editor="date" ${openPanel==='date'?'':'hidden'}><p>${label(language,'选择探索范围','Explore dates')}</p><div class="trip-actions">${[['3',label(language,'前后3天','±3 days')],['7',label(language,'前后7天','±7 days')],['month',label(language,'本月再找几组','More this month')]].map(([value,text])=>`<button type="button" data-trip-date-option="${value}">${text}</button>`).join('')}<button type="button" data-trip-date-option="custom">${label(language,'自定义日期','Custom dates')}</button></div><div class="trip-custom-dates"><label>${label(language,'出发','Depart')}<input type="date" data-trip-field="departure" value="${e(window?.departure||'')}"></label><label>${label(language,'返程','Return')}<input type="date" data-trip-field="return" value="${e(window?.returnDate||'')}"></label><button type="button" data-trip-action="apply-date">${label(language,'应用','Apply')}</button></div><p class="trip-editor-feedback" aria-live="polite"></p></div><div class="trip-inline-editor" data-trip-editor="duration" ${openPanel==='duration'?'':'hidden'}><p>${label(language,'旅行几晚？','How many nights?')}</p><div class="trip-actions">${[3,4,5,6,7].map(value=>`<button type="button" data-trip-nights="${value}">${value}${label(language,'晚',' nights')}</button>`).join('')}</div><label>${label(language,'自定义','Custom')}<input type="number" min="1" max="30" data-trip-field="nights" value="${e(nights)}"></label><button type="button" data-trip-action="apply-duration">${label(language,'应用','Apply')}</button></div></section>`;
}

const band=(value,language)=>({low:label(language,'低','Low'),medium:label(language,'中','Medium'),high:label(language,'高','High'),short:label(language,'短','Short'),long:label(language,'长','Long')})[value]||value;
const curvePath=points=>points.length?points.slice(1).reduce((path,point,index)=>{const previous=points[index],bend=index%2?-7:7;return `${path} Q ${(previous.x+point.x)/2} ${(previous.y+point.y)/2+bend} ${point.x} ${point.y}`;},`M ${points[0].x} ${points[0].y}`):'';
const schematicPoints=[{x:17,y:24},{x:49,y:16},{x:79,y:38},{x:66,y:73},{x:27,y:69},{x:48,y:45}];
const visitDuration=activity=>{const start=activity?.startTime,end=activity?.endTime;if(!/^\d\d:\d\d$/.test(start||'')||!/^\d\d:\d\d$/.test(end||''))return null;const minutes=(Number(end.slice(0,2))*60+Number(end.slice(3,5)))-(Number(start.slice(0,2))*60+Number(start.slice(3,5)));return minutes>0?minutes:null;};
const licensedPoiImage=place=>[place?.image,...(place?.photos||[])].find(image=>image&&(image.src||image.url)&&image.author&&image.license&&image.sourceUrl)||null;
const routeContext=(activity,neighbor,language,direction)=>{if(!neighbor)return null;const segment=direction==='previous'?activity:neighbor,verified=segment.routeState==='verified'&&Number.isFinite(segment.travelMinutes);return {name:neighbor.place.names[language==='zh'?'zh':'en'],verified,durationMinutes:verified?segment.travelMinutes:null};};
export function buildPoiInteractionModel(day,activityIndex,language='zh'){
 const activities=day?.activities||[],activity=activities[activityIndex];if(!activity)return null;const place=activity.place||{},localized=place.names?.[language==='zh'?'zh':'en']||place.displayName||place.canonicalName||'',canonical=place.canonicalName||place.names?.en||localized,minutes=visitDuration(activity),reason=activity.recommendationReason||place.recommendationReason||place.planningReason||null;
 return {id:activity.id,day:day.day,index:activityIndex,localizedName:localized,canonicalName:place.source!=='planning_template'&&place.source!=='user'&&canonical!==localized?canonical:null,category:place.category||null,coordinates:place.coordinates||null,image:licensedPoiImage(place),recommendationReason:reason,durationMinutes:minutes,durationState:minutes==null?'unavailable':activity.durationVerificationState==='LIVE_VERIFIED'?'verified':'planning_guidance',verificationState:place.verificationState||null,previous:routeContext(activity,activities[activityIndex-1],language,'previous'),next:routeContext(activity,activities[activityIndex+1],language,'next'),travelSignal:place.travelSignal?.curated===true?place.travelSignal:null};
}
const routeContextHtml=(model,language)=>{const item=(context,kind)=>context?`<div class="poi-route-${kind}"><small>${kind==='previous'?label(language,'上一站','Previous'):label(language,'下一站','Next')}</small><strong>${e(context.name)}</strong><span>${context.verified?`${label(language,'已核验 · 步行','Verified · walk')} ${context.durationMinutes} min`:label(language,'路线待验证','Route unverified')}</span></div>`:'<div aria-hidden="true"></div>';return model.previous||model.next?`<div class="poi-route-context" data-route-context="${e(model.id)}">${item(model.previous,'previous')}<i aria-hidden="true">●</i>${item(model.next,'next')}</div>`:'';};
const renderPoiExpansion=(model,point,language)=>{const image=model.image,stay=model.durationMinutes==null?'':model.durationState==='verified'?`${label(language,'已核验停留时间','Verified visit duration')} · ${durationText(model.durationMinutes,language)}`:`${label(language,'途米规划建议','Timing planning guidance')} · ${label(language,'约','About')} ${durationText(model.durationMinutes,language)}`;return `<article class="poi-expansion" data-poi-expansion="${e(model.id)}" style="--origin-x:${point.x}%;--origin-y:${point.y/86*100}%" hidden><button type="button" class="poi-contract" data-poi-contract="${e(model.id)}" aria-label="${label(language,'收起地点','Close place')}">×</button><div class="poi-expansion-visual ${image?'has-image':'is-fallback'}">${image?`<img src="${e(image.src||image.url)}" alt="${e(image.description||model.localizedName)}" loading="lazy" decoding="async"><small>${label(language,'照片','Photo')}: <a href="${e(image.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e(image.author)}</a> · ${e(image.license)}</small>`:`<i aria-hidden="true"></i>`}</div><div class="poi-expansion-copy"><span>${model.category?e(displayLabel(model.category,language)):label(language,'行程地点','Itinerary place')}</span><h4>${e(model.localizedName)}</h4>${model.canonicalName?`<p class="poi-canonical-name">${e(model.canonicalName)}</p>`:''}${stay?`<p class="poi-stay-guidance">${e(stay)}</p>`:''}${model.recommendationReason?`<div class="poi-reason"><small>${label(language,'为什么推荐','Why Timing recommends it')}</small><p>${e(model.recommendationReason)}</p></div>`:''}${routeContextHtml(model,language)}${model.travelSignal?`<blockquote><small>${label(language,'旅行信号 · 精选内容','Travel signal · curated')}</small>${e(model.travelSignal[language==='zh'?'zh':'en']||model.travelSignal.text||'')}</blockquote>`:''}<div class="poi-expansion-actions"><button type="button" data-trip-action="swap" data-day="${model.day}" data-activity="${e(model.id)}">${label(language,'换一个','Swap')}</button><button type="button" data-trip-action="extend-stay" data-day="${model.day}" data-activity="${e(model.id)}">${label(language,'多待一会','Stay longer')}</button><button type="button" data-trip-action="remove" data-day="${model.day}" data-activity="${e(model.id)}">${label(language,'删除','Remove')}</button><button type="button" data-poi-contract="${e(model.id)}">${label(language,'收起','Close')}</button></div></div></article>`;};
export function renderTravelFootprintMap(day,language='zh'){
 const activities=day.activities||[];if(!activities.length)return '';
 const names=activities.map(activity=>activity.place.names[language==='zh'?'zh':'en']);
 const systems=new Set(activities.map(activity=>activity.place.coordinates?.coordinateSystem).filter(Boolean));
 const geographic=systems.size<=1&&activities.every(activity=>Number.isFinite(activity.place.coordinates?.lat)&&Number.isFinite(activity.place.coordinates?.lng??activity.place.coordinates?.lon));
 let points;
 if(geographic){const coordinates=activities.map(activity=>activity.place.coordinates),lats=coordinates.map(p=>p.lat),lons=coordinates.map(p=>p.lng??p.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons);points=coordinates.map(point=>({x:14+((point.lng??point.lon)-minLon)/(maxLon-minLon||1)*72,y:16+(maxLat-point.lat)/(maxLat-minLat||1)*58}));}
 else points=activities.map((_,index)=>schematicPoints[index%schematicPoints.length]);
 const title=geographic?label(language,'足迹图','Travel footprint'):label(language,'行程示意','Schematic plan'),note=geographic?label(language,'按地点相对方位绘制 · 连线不是导航路线','Relative positions · line is not a navigation route'):label(language,'暂无坐标 · 不代表真实方位','Coordinates unavailable · not geographic');
 const segments=points.slice(1).map((point,index)=>`<path class="footprint-route footprint-segment" data-route-from="${e(activities[index].id)}" data-route-to="${e(activities[index+1].id)}" d="${curvePath([points[index],point])}"/>`).join('');
 const markers=points.map((point,index)=>`<button type="button" class="footprint-marker interactive-travel-point ${index===0?'is-start ':''}${index===points.length-1?'is-end ':''}${point.x>64?'label-left':''}" style="--x:${point.x}%;--y:${point.y/86*100}%" data-route-stop="${e(activities[index].id)}" data-poi-trigger="map" data-day="${day.day}" aria-expanded="false" aria-controls="poi-${day.day}-${e(activities[index].id)}" aria-label="${index+1}. ${e(names[index])}"><b>${index+1}</b><span>${e(names[index])}</span></button>`).join('');
 const expansions=points.map((point,index)=>renderPoiExpansion(buildPoiInteractionModel(day,index,language),point,language).replace('class="poi-expansion"',`id="poi-${day.day}-${e(activities[index].id)}" class="poi-expansion"`)).join('');
 return `<div class="travel-footprint-map" data-route-state="${geographic?'coordinates':'schematic'}" data-coordinate-system="${geographic?e([...systems][0]||'unspecified'):'none'}" aria-label="${e(title)}"><div class="footprint-heading"><strong>${title}</strong><small>${note}</small></div><div class="footprint-canvas"><svg viewBox="0 0 100 86" aria-hidden="true"><path class="footprint-terrain" d="M4 26 C22 8 33 31 52 17 S81 7 97 22 M5 71 C25 53 44 83 64 66 S86 53 98 72"/>${segments}</svg>${markers}${expansions}</div></div>`;
}
export const renderRoutePreview=renderTravelFootprintMap;

const renderResearchSources=(research,language)=>{const sources=[...new Map((research?.sources||[]).filter(source=>source?.sourceUrl).map(source=>[source.sourceUrl,source])).values()];if(!sources.length)return '';return `<details class="trip-research-sources"><summary>${label(language,'数据与来源','Data and sources')}</summary><p>${label(language,'地点名称与分类来自开放旅行资料或已配置的地点服务；具体营业时间仍需确认。','Place names and categories come from open travel data or a configured place provider; opening hours still require confirmation.')}</p><ul>${sources.map(source=>`<li><a href="${e(source.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e(source.provider||source.attribution||'Source')}</a>${source.license?` · ${source.licenseUrl?`<a href="${e(source.licenseUrl)}" target="_blank" rel="noopener noreferrer">${e(source.license)}</a>`:`<span>${e(source.license)}</span>`}`:''}${source.attribution?` · <span>${e(source.attribution)}</span>`:''}</li>`).join('')}</ul></details>`;};

const approximateTime=(activity,language)=>activity.place.source==='user'?label(language,'时间待安排','Time to arrange'):activity.schedulePrecision==='verified'?`${e(activity.startTime)}–${e(activity.endTime)}`:activity.schedulePrecision==='user_adjusted'?`${e(activity.startTime)} · ${label(language,'已调整','set by you')}`:`${label(language,'约','About ')} ${e(activity.startTime)}`;
export function renderTripSections(experience,language='zh'){
 const transport=experience.transport.options.map(option=>{const title=displayLabel(option.mode,language),primary=option.allowed&&option.mode===experience.transport.preferredMode;
  const fit=!option.allowed?label(language,'不符合已选交通限定','Excluded by your transport requirement'):option.suitability==='not_applicable'?label(language,'不适用','Not applicable'):primary?label(language,'优先推荐','Recommended'):option.suitability==='medium'?label(language,'可选','Alternative'):label(language,'不优先','Lower priority');
  let verification=option.verification.status==='verified'&&option.verification.source==='live'?`${label(language,'已核验','Verified')} · Duffel · ${option.currency==='CNY'?'¥'+Math.round(option.price).toLocaleString('en-US'):label(language,'价格待核验','Price unverified')}`:option.quote?`${label(language,'演示参考','Demo reference')} · ${option.currency==='CNY'?'¥'+Math.round(option.price).toLocaleString('en-US'):label(language,'价格待核验','Price unverified')}`:option.verification.status==='partially_verified'?label(language,'入口航班已核验 · 接驳与总价待核验','Entry flight verified · connection and total cost unverified'):option.suitability==='not_applicable'?'':`${option.mode==='train'?label(language,'实时车次与票价暂未接入 · ','Live schedules and fares unavailable · '):option.mode==='self_drive'?label(language,'未接入路线、路费与驾车时间 · ','Route, tolls and drive time unavailable · '):''}${label(language,'预算参考','Cost reference')}：${band(option.costBand,language)} · ${label(language,'时间参考','Time reference')}：${band(option.durationBand,language)} · ${label(language,'精确数据待接入','exact data unavailable')}`;
  const flight=option.mode==='flight'&&option.quote?renderFlightDetails(option.quote,option.verification.source,language,{from:displayCity(experience.trip.origin,language),to:displayCity(experience.trip.destination,language)}):'';
  const routeAction=option.mode!=='flight'&&option.suitability!=='not_applicable'?`<a class="trip-link-action" href="${e(navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en).directionsUrl({names:{en:experience.trip.destination}}))}" target="_blank" rel="noopener noreferrer">${label(language,'查看路线','View route')} →</a>`:'';
  const stateClass=!option.allowed||option.suitability==='not_applicable'?' transport-muted':primary?' transport-primary':option.verification.status==='verified'?' transport-available':' transport-unverified';
  const icon={flight:'icon-flight',train:'icon-train',self_drive:'icon-car'}[option.mode];return `<div class="transport-row${stateClass}"><div><svg class="transport-icon" aria-hidden="true"><use href="#${icon}"/></svg><strong>${e(title)}</strong><span>${e(fit)}</span></div><div class="transport-detail"><p>${e(verification)}</p>${option.suitability!=='not_applicable'?`<small>${e(option.reason?.[language==='zh'?'zh':'en']||'')}</small>`:''}${flight}${routeAction}</div></div>`;
 }).join('');
 const nav=navigationForCountry(destinationIdentity(experience.trip.destination).countryNames.en);
  const itinerary=experience.itinerary.days.map((day,dayIndex)=>{const dayNames=(day.activities||[]).map(activity=>activity.place.names[language==='zh'?'zh':'en']);const activities=(day.activities||[]).map((activity,index)=>{const planning=activity.place.source==='planning_template',user=activity.place.source==='user',live=activity.place.verificationState==='LIVE_VERIFIED',openSource=activity.place.verificationState==='OPEN_SOURCE_VERIFIED'||activity.place.source==='wikivoyage';return `<div class="trip-activity" data-itinerary-stop="${e(activity.id)}" data-day="${day.day}"><button type="button" class="trip-time" data-trip-action="edit-time" data-day="${day.day}" data-activity="${e(activity.id)}">${approximateTime(activity,language)}</button><div><button type="button" class="trip-place-trigger interactive-travel-point" data-route-stop="${e(activity.id)}" data-poi-trigger="itinerary" data-day="${day.day}" aria-expanded="false" aria-controls="poi-${day.day}-${e(activity.id)}"><i>${index+1}</i><strong>${e(activity.place.names[language==='zh'?'zh':'en'])}</strong></button><small>${user?label(language,'你添加的地点 · 待核验','Your place · unverified'):planning?label(language,'规划方向 · 具体地点待确认','Planning direction · place to confirm'):live?label(language,`地点已核验 · ${activity.place.sourceAttribution?.provider||'实时地点服务'} · 营业时间未查询`,`Verified place · ${activity.place.sourceAttribution?.provider||'live place provider'} · hours not requested`):openSource?label(language,'开放旅行资料 · Wikivoyage · 营业时间未查询','Open travel data · Wikivoyage · hours not requested'):activity.openingHoursState==='checked'?label(language,'营业时间已核验','Opening hours checked'):label(language,'地点来自精选目录 · 营业时间待确认','Place from curated catalog · opening hours to confirm')}</small><div class="trip-time-editor" data-time-editor="${e(activity.id)}" hidden><label>${label(language,'开始时间','Start time')}<input type="time" value="${e(activity.startTime==='--:--'?'09:30':activity.startTime)}" data-time-start></label><label>${label(language,'停留分钟','Duration (minutes)')}<input type="number" min="30" max="360" step="15" value="${activity.startTime==='--:--'?90:Math.max(30,(Number(activity.endTime.slice(0,2))*60+Number(activity.endTime.slice(3,5)))-(Number(activity.startTime.slice(0,2))*60+Number(activity.startTime.slice(3,5))))}" data-time-duration></label><button type="button" data-trip-action="apply-time" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'应用','Apply')}</button></div><div class="trip-activity-actions">${user||planning?'':`<a href="${e(nav.mapUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'查看地图','View map')}</a><a href="${e(nav.directionsUrl(activity.place))}" target="_blank" rel="noopener noreferrer">${label(language,'导航','Navigate')}</a>`}<button type="button" data-trip-action="swap" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'换一个','Swap')}</button><button type="button" data-trip-action="remove" data-day="${day.day}" data-activity="${e(activity.id)}">${label(language,'删除','Remove')}</button></div></div></div>`;}).join('');
  const routeSummary=day.routeState==='verified'?`<p class="route-summary">${label(language,'今日移动约','Today’s travel: about')} ${(day.routeDistanceMeters/1000).toFixed(1)} km · ${label(language,'交通约','travel about')} ${day.routeDurationMinutes} min</p>`:'';
  return `<details class="itinerary-day" data-trip-day="${day.day}" ${dayIndex===0?'open':''}><summary><b>${language==='zh'?`DAY ${day.day}`:`DAY ${day.day}`}</b><span><strong>${e(day.labels[language==='zh'?'zh':'en'])}</strong><small>${e(dayNames.join(' · '))}</small></span><i aria-hidden="true">›</i></summary><div class="itinerary-day-panel"><div class="itinerary-day-layout"><div class="itinerary-timeline">${activities}</div><div>${renderTravelFootprintMap(day,language)}${routeSummary}</div></div><div class="itinerary-day-actions"><button type="button" class="trip-add-wish" data-trip-action="add-wish" data-day="${day.day}">＋ ${label(language,'我有想去的地方','I have a place in mind')}</button><button type="button" data-trip-action="adjust-day" data-day="${day.day}">${label(language,'调整这一天','Adjust day')}</button></div></div></details>`;}).join('');
 const stay=experience.stay,primary=stay.primaryArea||stay.areas[0],alternatives=stay.areas.map((area,index)=>`<li class="${index===0?'active':''}"><strong>${e(area.labels[language==='zh'?'zh':'en'])}</strong><span>${index===0?label(language,'最适合当前路线','Best for this route'):area.role==='quiet'?label(language,'更安静','Quieter'):area.role==='value'?label(language,'更省预算','Better value'):label(language,'更方便','More convenient')}</span></li>`).join('');
 const placeNotice=experience.itinerary.status==='planning_skeleton'?label(language,'地点研究暂不可用；规划方向可编辑，具体地点仍需确认。','Place research is unavailable; planning directions are editable and exact places need confirmation.'):experience.research?.researchStatus==='LIVE_VERIFIED'?label(language,'地点来自已配置的实时地点服务；营业时间与未核验路线仍需确认。','Places come from a configured live place service; hours and unverified routes still require confirmation.'):experience.research?.researchStatus==='OPEN_SOURCE_VERIFIED'?label(language,'地点来自开放旅行资料；时间为约略规划，营业时间与导航路线仍待确认。','Places come from open travel data; times are approximate, and hours and navigation remain unverified.'):label(language,'地点来自精选目录；未核验的时间均为约略规划，营业时间与导航路线仍待确认。','Places come from a curated catalog; unverified times are approximate, and hours and navigation remain unverified.');
 const itinerarySection=`<section class="trip-module" data-trip-module="itinerary"><div class="trip-module-heading"><span>03</span><h3>${label(language,'怎么玩','Itinerary')}</h3></div><p class="trip-module-intro">${label(language,'途米已经排好一套基础行程，你可以从这里修改。','Timing has prepared a complete starting itinerary. Edit it from here.')}</p>${renderStyleControls(experience,language)}<div class="itinerary-days">${itinerary}</div><div class="itinerary-command"><label>${label(language,'直接告诉途米怎么改','Tell Timing what to change')}<input type="text" data-itinerary-command placeholder="${label(language,'例如：第二天晚一点出门 / 不要卢浮宫 / 想加蒙马特','For example: start Day 2 later / remove the Louvre / add Montmartre')}"></label><button type="button" data-trip-action="apply-itinerary-command">${label(language,'修改行程','Update plan')}</button><p aria-live="polite"></p></div><p class="trip-availability">${placeNotice}</p>${renderResearchSources(experience.research,language)}</section>`;
 const staySection=`<section class="trip-module" data-trip-module="stay"><div class="trip-module-heading"><span>04</span><h3>${label(language,'住哪里更合适','Where to stay')}</h3></div><p class="trip-module-intro"><strong>${label(language,'最适合当前路线：','Best for this route: ')}${e(primary?.labels[language==='zh'?'zh':'en']||'')}</strong><br>${e(stay.reason?.[language==='zh'?'zh':'en']||'')}</p><ul class="stay-options">${alternatives}</ul><button type="button" class="stay-cta" data-trip-action="stay">${label(language,'查看住宿','View stays')} →</button><p class="stay-feedback trip-availability" aria-live="polite">${label(language,'住宿实时价格与库存暂未接入','Live hotel prices and inventory are not connected')}</p></section>`;
 return `<section class="trip-module" data-trip-module="transport"><div class="trip-module-heading"><span>02</span><h3>${label(language,'怎么去','Transport')}</h3></div><div class="transport-rows">${transport}</div></section>${itinerarySection}${staySection}`;
}
